const solid = c => [{type:"SOLID", color:c}];

function mkText(chars, style, size, color, opts={}){
  const t = figma.createText();
  t.fontName = {family:"Lato", style};
  t.fontSize = size;
  t.characters = chars;
  t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value:opts.lh, unit:"PIXELS"};
  if (opts.name) t.name = opts.name;
  if (opts.align) t.textAlignHorizontal = opts.align;
  return t;
}
function mkFrame(name, w, h, fill, radius){
  const f = figma.createFrame();
  f.name = name; f.resize(w,h);
  f.fills = fill? solid(fill) : [];
  if (radius!==undefined) f.cornerRadius = radius;
  f.clipsContent = true;
  return f;
}
function iconAt(node, x, y){ node.x=x; node.y=y; return node; }
function recolorIcon(inst, color){
  const walk = n => {
    if ("strokes" in n && n.strokes && n.strokes.length) { try{ n.strokes = solid(color);}catch(e){} }
    if ("fills" in n && n.type!=="INSTANCE" && n.type!=="COMPONENT" && n.fills && n.fills.length && n.fills[0].type==="SOLID" && n.visible) { try{ n.fills = solid(color);}catch(e){} }
    if ("children" in n) n.children.forEach(walk);
  };
  inst.children.forEach(walk);
}
