// photo clipped in rounded frame
async function photoBox(key, w, h, radius){
  const box = mkFrame("Photo", w, h, C.line, radius);
  const p = await photoInst(key);
  p.resize(w,h); p.x=0; p.y=0; p.name="PhotoImage";
  box.appendChild(p);
  return box;
}

